Fragment:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n//\n// Simple passthrough fragment shader\n//\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\nuniform float range;\nuniform vec4 colorMatch_A;\nuniform vec4 colorReplace_A;\nuniform vec4 colorMatch_B;\nuniform vec4 colorReplace_B;\nuniform vec4 colorMatch_C;\nuniform vec4 colorReplace_C;\nuniform vec4 colorMatch_D;\nuniform vec4 colorReplace_D;\nvoid main()\n{\n	vec4 pixelColor = v_vColour * texture2D( gm_BaseTexture, v_vTexcoord );\n	\n	float newRange = range / 255.0;\n	\n	if(abs(pixelColor.r - colorMatch_A.r) <= newRange) {\n		if(abs(pixelColor.g - colorMatch_A.g) <= newRange) {\n			if(abs(pixelColor.b - colorMatch_A.b) <= newRange) {\n				pixelColor.rgb = colorReplace_A.rgb;\n			}\n		}\n	}\n	\n	if(abs(pixelColor.r - colorMatch_B.r) <= newRange) {\n		if(abs(pixelColor.g - colorMatch_B.g) <= newRange) {\n			if(abs(pixelColor.b - colorMatch_B.b) <= newRange) {\n				pixelColor.rgb = colorReplace_B.rgb;\n			}\n		}\n	}\n	\n	if(abs(pixelColor.r - colorMatch_C.r) <= newRange) {\n		if(abs(pixelColor.g - colorMatch_C.g) <= newRange) {\n			if(abs(pixelColor.b - colorMatch_C.b) <= newRange) {\n				pixelColor.rgb = colorReplace_C.rgb;\n			}\n		}\n	}\n	\n	if(abs(pixelColor.r - colorMatch_D.r) <= newRange) {\n		if(abs(pixelColor.g - colorMatch_D.g) <= newRange) {\n			if(abs(pixelColor.b - colorMatch_D.b) <= newRange) {\n				pixelColor.rgb = colorReplace_D.rgb;\n			}\n		}\n	}\n	\n    gl_FragColor = pixelColor;\n}\n",
